properties.Script_1:
// Link clicked

importClass("VProcess");
var url = "";
url = theRoot.varToString("EVENT_PARAMS", 1);

var finRuta = url.indexOf("?");
var ruta = finRuta > -1 ? url.substring(0, finRuta) : url;
var posBarra = ruta.lastIndexOf("/");
var accion = posBarra > -1 ? ruta.substring(posBarra + 1) : ruta;

if (accion === "resumen") {
    var acumJson = theRoot.varToString("RESULTADO_IMPORT_ACUM");
    var acum = { altas: 0, modificaciones: 0, errores: 0, mensajesError: [] };
    if (acumJson) {
        try { acum = JSON.parse(acumJson); } catch (e) {};
    };

    var mensaje = "Importación finalizada.\n\n" +
        "Altas: " + acum.altas + "\n" +
        "Modificaciones: " + acum.modificaciones + "\n" +
        "Errores: " + acum.errores;

    // Desglose por tabla -- solo lo produce IMP_DAT_MULTI (multi-tabla); IMP_DAT (una sola tabla)
    // no manda "porTabla" porque con una sola tabla el total ya es el desglose.
    if (acum.porTabla) {
        var lineasPorTabla = [];
        for (var tablaIdRef in acum.porTabla) {
            var t = acum.porTabla[tablaIdRef];
            var partes = [];
            if (t.altas) partes.push(t.altas + (t.altas === 1 ? " alta" : " altas"));
            if (t.modificaciones) partes.push(t.modificaciones + " modificacion" + (t.modificaciones === 1 ? "" : "es"));
            if (t.errores) partes.push(t.errores + (t.errores === 1 ? " error" : " errores"));
            lineasPorTabla.push(tablaIdRef + ": " + (partes.length ? partes.join(", ") : "sin cambios"));
        };
        if (lineasPorTabla.length) {
            mensaje = mensaje + "\n\nDesglose por tabla:\n" + lineasPorTabla.join("\n");
        };
    };

    if (acum.mensajesError && acum.mensajesError.length) {
        var MAX_ERRORES_MOSTRADOS = 20;
        var listaErrores = acum.mensajesError.slice(0, MAX_ERRORES_MOSTRADOS).join("\n");
        mensaje = mensaje + "\n\nDetalle de errores:\n" + listaErrores;
        if (acum.mensajesError.length > MAX_ERRORES_MOSTRADOS) {
            mensaje = mensaje + "\n... y " + (acum.mensajesError.length - MAX_ERRORES_MOSTRADOS) + " más.";
        };
    };

    alert(mensaje);
    theRoot.setVar("RESULTADO_IMPORT_ACUM", "");
} else if (accion === "importar") {
    var posLote = url.indexOf("?lote=");
    var loteJson = decodeURIComponent(url.substring(posLote + 6));
    var lote = JSON.parse(loteJson);
    var cabeceraLote = lote[0];

    if (cabeceraLote.loteNum === 1) {
        theRoot.setVar("RESULTADO_IMPORT_ACUM", JSON.stringify({ altas: 0, modificaciones: 0, errores: 0, mensajesError: [] }));
    };

    var proceso = new VProcess(theRoot);
    proceso.setProcess("sygemat_corralon_dat/IMP_DAT");
    proceso.setVar("DAT", loteJson);
    proceso.exec(VProcess.RunInServer);

    var resultadoLoteJson = proceso.varToString("DAT");
    var resultadoLote = null;
    try { resultadoLote = JSON.parse(resultadoLoteJson); } catch (e) {};

    if (resultadoLote) {
        var acumActual = JSON.parse(theRoot.varToString("RESULTADO_IMPORT_ACUM") ||
            "{\"altas\":0,\"modificaciones\":0,\"errores\":0,\"mensajesError\":[]}");
        acumActual.altas = acumActual.altas + resultadoLote.altas;
        acumActual.modificaciones = acumActual.modificaciones + resultadoLote.modificaciones;
        acumActual.errores = acumActual.errores + resultadoLote.errores;
        if (resultadoLote.mensajesError && resultadoLote.mensajesError.length) {
            for (var m = 0; m < resultadoLote.mensajesError.length; m++) {
                acumActual.mensajesError.push(resultadoLote.mensajesError[m]);
            };
        };
        theRoot.setVar("RESULTADO_IMPORT_ACUM", JSON.stringify(acumActual));
    };
} else if (accion === "importarmultitabla") {
    // Gemela de "importar", pero llamando a IMP_DAT_MULTI en vez de IMP_DAT. El acumulado
    // (RESULTADO_IMPORT_ACUM) y el mensaje final ("resumen") son compartidos -- solo aquí, al
    // recibir el resultado de IMP_DAT_MULTI, se acumula además "porTabla" (el desglose por tabla,
    // que IMP_DAT no produce porque con una sola tabla no hace falta).
    var posLoteM = url.indexOf("?lote=");
    var loteJsonM = decodeURIComponent(url.substring(posLoteM + 6));
    var loteM = JSON.parse(loteJsonM);
    var cabeceraLoteM = loteM[0];

    if (cabeceraLoteM.loteNum === 1) {
        theRoot.setVar("RESULTADO_IMPORT_ACUM", JSON.stringify({ altas: 0, modificaciones: 0, errores: 0, mensajesError: [], porTabla: {} }));
    };

    var procesoM = new VProcess(theRoot);
    procesoM.setProcess("sygemat_corralon_dat/IMP_DAT_MULTI");
    procesoM.setVar("DAT", loteJsonM);
    procesoM.exec(VProcess.RunInServer);

    var resultadoLoteJsonM = procesoM.varToString("DAT");
    var resultadoLoteM = null;
    try { resultadoLoteM = JSON.parse(resultadoLoteJsonM); } catch (e) {};

    if (resultadoLoteM) {
        var acumActualM = JSON.parse(theRoot.varToString("RESULTADO_IMPORT_ACUM") ||
            "{\"altas\":0,\"modificaciones\":0,\"errores\":0,\"mensajesError\":[],\"porTabla\":{}}");
        acumActualM.altas = acumActualM.altas + resultadoLoteM.altas;
        acumActualM.modificaciones = acumActualM.modificaciones + resultadoLoteM.modificaciones;
        acumActualM.errores = acumActualM.errores + resultadoLoteM.errores;
        if (resultadoLoteM.mensajesError && resultadoLoteM.mensajesError.length) {
            for (var mm = 0; mm < resultadoLoteM.mensajesError.length; mm++) {
                acumActualM.mensajesError.push(resultadoLoteM.mensajesError[mm]);
            };
        };
        if (resultadoLoteM.porTabla) {
            if (!acumActualM.porTabla) acumActualM.porTabla = {};
            for (var tablaIdRefM in resultadoLoteM.porTabla) {
                if (!acumActualM.porTabla[tablaIdRefM]) {
                    acumActualM.porTabla[tablaIdRefM] = { altas: 0, modificaciones: 0, errores: 0 };
                };
                acumActualM.porTabla[tablaIdRefM].altas = acumActualM.porTabla[tablaIdRefM].altas + resultadoLoteM.porTabla[tablaIdRefM].altas;
                acumActualM.porTabla[tablaIdRefM].modificaciones = acumActualM.porTabla[tablaIdRefM].modificaciones + resultadoLoteM.porTabla[tablaIdRefM].modificaciones;
                acumActualM.porTabla[tablaIdRefM].errores = acumActualM.porTabla[tablaIdRefM].errores + resultadoLoteM.porTabla[tablaIdRefM].errores;
            };
        };
        theRoot.setVar("RESULTADO_IMPORT_ACUM", JSON.stringify(acumActualM));
    };
} else if (accion === "guardarplantilla") {
    var posPlantilla = url.indexOf("?plantilla=");
    var plantillaJson = decodeURIComponent(url.substring(posPlantilla + 11));
    var procesoGuardar = new VProcess(theRoot);
    procesoGuardar.setProcess("sygemat_corralon_dat/GUARDAR_PLANTILLA");
    procesoGuardar.setVar("DAT", plantillaJson);
    procesoGuardar.exec(VProcess.RunInThisThread);
};
